#include <LiquidCrystal.h> // Подключаем стандартную библиотеку для экрана

// Инициализируем библиотеку с номерами пинов интерфейса шилда
LiquidCrystal lcd(8, 9, 4, 5, 6, 7); 

void setup() {
  lcd.begin(16, 2);              // Указываем размер экрана: 16 символов, 2 строки
  lcd.setCursor(0, 0);           // Ставим курсор в начало первой строки
  lcd.print("Arduino Shield");   // Выводим приветственный текст
}

void loop() {
  int x = analogRead(A0);        // Считываем значение с пина кнопок A0
  lcd.setCursor(0, 1);           // Переходим на вторую строку

  // Определяем, какая именно кнопка нажата по уровню напряжения
  if (x < 60) {
    lcd.print("Button: RIGHT ");
  } else if (x < 200) {
    lcd.print("Button: UP    ");
  } else if (x < 400) {
    lcd.print("Button: DOWN  ");
  } else if (x < 600) {
    lcd.print("Button: LEFT  ");
  } else if (x < 800) {
    lcd.print("Button: SELECT");
  } else {
    lcd.print("Press any key "); // Если ничего не нажато
  }
}
